package com.bank.signaturemanagement.repository; import com.bank.signaturemanagement.entity.SignatureBookAccess; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface SignatureBookAccessRepository extends JpaRepository<SignatureBookAccess,Long>{@Query("select count(a) from SignatureBookAccess a where a.book.id=:book and a.active=true and (a.user.id=:user or a.role.id=:role)")long countAccess(@Param("book")Long book,@Param("user")Long user,@Param("role")Long role);Optional<SignatureBookAccess>findByBookIdAndUserId(Long book,Long user);Optional<SignatureBookAccess>findByBookIdAndRoleId(Long book,Long role);@EntityGraph(attributePaths={"user","role","grantedBy"})List<SignatureBookAccess>findByBookIdOrderByGrantedAtDesc(Long book);}
